import assert from 'node:assert/strict';import{mkdirSync,readFileSync,writeFileSync}from'node:fs';import{chromium,webkit}from'playwright';import{chapterHash}from'../lib/practice-chapters.ts';
const base=process.env.KLINK_TEST_URL||'http://127.0.0.1:18996',out=process.env.KLINK_GOALS_OUTPUT||'outputs/learning-goals-20261101/copy';mkdirSync(out,{recursive:true});const row=JSON.parse(readFileSync('data/klink-production-index.json')).find(r=>r.id==='production:copy:alfa-c:KSW-AC-TN-001-020'),exercises=JSON.parse(readFileSync('public'+row.url)).exercises,checks=[],errors=[];
for(const[engine,type]of Object.entries({chromium,webkit})){const browser=await type.launch();try{for(const width of[320,390])for(const index of[0,4,19]){const e=exercises[index],p=await browser.newPage({viewport:{width,height:844},hasTouch:true});p.on('pageerror',e=>errors.push(e.message));await p.addInitScript(([id,exerciseId])=>{localStorage.setItem('klink.group.v1:chapter:copy:'+id+':copy',JSON.stringify({version:1,done:false,exerciseId}));localStorage.setItem('klink.exercise-view.v1','{"photo":false,"text":false}');localStorage.setItem('klink.goals.copy','kept');},[row.id,e.exerciseId]);await p.goto(base+'/'+chapterHash({chapter:'writing',activity:'copy',collection:row.id,level:row.level,help:row.help}));const root=p.locator('[data-exercise-id]');await root.waitFor();assert.equal(await root.getAttribute('data-exercise-id'),e.exerciseId);const model=p.locator('.cp-task-prompt strong');assert.equal(await model.innerText(),e.exampleWord);assert(await model.isVisible());await p.getByRole('button',{name:'Over deze oefening',exact:true}).press('Enter');const dialog=p.getByRole('dialog');await dialog.waitFor();assert.equal(await dialog.locator('[data-learning-goal]').getAttribute('data-learning-goal'),'overschrijven');assert.equal(await dialog.locator('.cp-learner-goal p').innerText(),'Je oefent om de tekst precies over te nemen.');await p.keyboard.press('Escape');await dialog.waitFor({state:'hidden'});const field=p.locator('.cp-text-entry input');await field.fill(e.exampleWord.toUpperCase());await field.press('Enter');assert((await p.locator('.cp-exercise-feedback output').innerText()).includes('Probeer opnieuw'));assert(await p.locator('[data-practice-next]').isDisabled());await field.fill(e.exampleWord);await field.press('Enter');assert(await p.locator('[data-practice-next]').isEnabled());assert.equal(await p.evaluate(()=>localStorage.getItem('klink.goals.copy')),'kept');checks.push({engine,width,exerciseId:e.exerciseId,goal:true,modelAlwaysVisible:true,wrongCaseRejected:true,correctAccepted:true,nextAvailable:true,storagePreserved:true});await p.close();}}finally{await browser.close();writeFileSync(out+'/checks.json',JSON.stringify({base,checks,errors},null,2)+'\n');}}
assert.equal(checks.length,12);assert.deepEqual(errors,[]);console.log('PASS 12 newly published exact-copy word/phrase/sentence goal and answer-policy checks');
